async review(
  @Body() body: any,
) {

  try {

    return await this.service
      .review(body);

  } catch (error) {

    const message =
      error instanceof Error
        ? error.message
        : 'Warning review failed.';

    if (
      message.includes(
        'Resident context not found',
      )
    ) {
      throw new HttpException(
        message,
        HttpStatus.NOT_FOUND,
      );
    }

    if (
      message.includes('required') ||
      message.includes('Invalid') ||
      message.includes(
        'already been reviewed',
      )
    ) {
      throw new HttpException(
        message,
        HttpStatus.BAD_REQUEST,
      );
    }

    throw error;
  }
}

  async execute(
    @Param('carePlanId')
    carePlanId: string,

    @Param('action')
    rawAction: string,

    @Body()
    body: GovernanceBody,
  ) {

    const action =
      String(
        rawAction ?? '',
      )
        .trim()
        .toUpperCase();


    if (
      !CARE_PLAN_GOVERNANCE_ACTIONS
        .includes(
          action as
            CarePlanGovernanceAction,
        )
    ) {
      throw new BadRequestException(
        'Unsupported Care Plan governance action.',
      );
    }


    try {
      const data =
        await this.service
          .execute(
            carePlanId,
            action as
              CarePlanGovernanceAction,
            String(
              body?.actorId ?? '',
            ),
            String(
              body?.actorRole ?? '',
            ),
          );

      return {
        status:
          'OK',

        data,
      };
    } catch (error) {

      if (
        error instanceof
        HttpException
      ) {
        throw error;
      }

      const message =
        error instanceof Error
          ? error.message
          : String(error);


      if (
        message.includes(
          'not found',
        )
      ) {
        throw new NotFoundException(
          message,
        );
      }


      const businessErrors = [
        'required',
        'cannot govern',
        'not authorized',
        'Only a DRAFT',
        'Only an ACTIVE',
        'Only a SUSPENDED',
        'Only a DRAFT, ACTIVE, or SUSPENDED',
        'Unsupported Care Plan governance action',
      ];


      if (
        businessErrors.some(
          term =>
            message.includes(
              term,
            ),
        )
      ) {
        throw new BadRequestException(
          message,
        );
      }


      throw new HttpException(
        {
          statusCode:
            HttpStatus.INTERNAL_SERVER_ERROR,

          error:
            'Internal Server Error',

          message:
            'Unable to process Care Plan governance request.',
        },
        HttpStatus.INTERNAL_SERVER_ERROR,
      );
    }
  }
}

  async execute(
    @Param('careTaskId')
    careTaskId:
      string,

    @Param('action')
    action:
      string,

    @Body()
    input:
      CareTaskExecutionInput,
  ) {

    try {

      const data =
        await this.service
          .execute(
            careTaskId,
            action,
            input,
          );

      return {
        status:
          'OK',

        data,
      };

    } catch (
      error:
        unknown
    ) {

      if (
        error instanceof
        HttpException
      ) {
        throw error;
      }

      const message =
        error instanceof
          Error
          ? error.message
          : String(error);


      if (
        message.includes(
          'not found',
        )
      ) {
        throw new HttpException(
          {
            statusCode:
              HttpStatus.NOT_FOUND,

            error:
              'Not Found',

            message,
          },

          HttpStatus.NOT_FOUND,
        );
      }


      const businessTerms = [
        'required',
        'Only a ',
        'Only an ',
        'not authorized',
        'cannot mutate',
        'human owner',
        'already been accepted',
        'must be accepted',
        'Unsupported Care Task action',
      ];


      if (
        businessTerms.some(
          term =>
            message.includes(
              term,
            ),
        )
      ) {
        throw new HttpException(
          {
            statusCode:
              HttpStatus.BAD_REQUEST,

            error:
              'Bad Request',

            message,
          },

          HttpStatus.BAD_REQUEST,
        );
      }


      throw new HttpException(
        {
          statusCode:
            HttpStatus.INTERNAL_SERVER_ERROR,

          error:
            'Internal Server Error',

          message:
            'Unable to process Care Task request.',
        },

        HttpStatus.INTERNAL_SERVER_ERROR,
      );
    }
  }
}

